CREATE TYPE user_role AS ENUM ('USER','RJ','ADMIN'); CREATE TYPE show_status AS ENUM ('DRAFT','PUBLISHED','ARCHIVED');
CREATE TABLE profiles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name VARCHAR(80) NOT NULL,email VARCHAR(255) UNIQUE NOT NULL,avatar_url TEXT,role user_role NOT NULL DEFAULT 'USER',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE radio_stations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name TEXT NOT NULL,logo_url TEXT,stream_url TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OFFLINE',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE radio_shows (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),title VARCHAR(120) NOT NULL,description TEXT NOT NULL DEFAULT '',category VARCHAR(60) NOT NULL,thumbnail_url TEXT,status show_status NOT NULL DEFAULT 'DRAFT',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE show_hosts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),show_id UUID NOT NULL REFERENCES radio_shows(id) ON DELETE CASCADE,user_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,role TEXT NOT NULL DEFAULT 'HOST',UNIQUE(show_id,user_id));
CREATE TABLE program_schedule (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),show_id UUID NOT NULL REFERENCES radio_shows(id) ON DELETE CASCADE,start_time TIMESTAMPTZ NOT NULL,end_time TIMESTAMPTZ NOT NULL,recurrence TEXT NOT NULL DEFAULT 'ONCE',CHECK(end_time>start_time));
CREATE TABLE live_sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),show_id UUID NOT NULL REFERENCES radio_shows(id),started_at TIMESTAMPTZ NOT NULL DEFAULT now(),ended_at TIMESTAMPTZ,listener_count INTEGER NOT NULL DEFAULT 0 CHECK(listener_count>=0));
CREATE TABLE recordings (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),show_id UUID NOT NULL REFERENCES radio_shows(id),storage_path TEXT NOT NULL,playback_url TEXT,duration INTEGER NOT NULL CHECK(duration>0),status TEXT NOT NULL DEFAULT 'PROCESSING',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE favorites (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,show_id UUID NOT NULL REFERENCES radio_shows(id) ON DELETE CASCADE,UNIQUE(user_id,show_id));
CREATE TABLE listener_sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID REFERENCES profiles(id) ON DELETE SET NULL,anonymous_id TEXT,show_id UUID REFERENCES radio_shows(id),started_at TIMESTAMPTZ NOT NULL DEFAULT now(),ended_at TIMESTAMPTZ, CHECK(user_id IS NOT NULL OR anonymous_id IS NOT NULL));
CREATE TABLE notifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),title VARCHAR(120) NOT NULL,message TEXT NOT NULL,type TEXT NOT NULL,sent_at TIMESTAMPTZ);
CREATE INDEX schedule_time_idx ON program_schedule(start_time); CREATE INDEX recording_show_idx ON recordings(show_id); CREATE INDEX listener_show_idx ON listener_sessions(show_id);
